cd /home/experimenter/experiments/runs/2026-10-01_01-43-58_claim-office-example-mapping_external-kesseler-2026-09-30-cc_opus-5-5-no-thinking; cat > src/premium.ts <<'EOF'
export interface Item {
  type: string;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

export function basePremium(items: Item[]): number {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  let sum = 0;
  for (const [type, count] of counts) {
    sum += type === 'rune' && count === BLOCK_SIZE ? BLOCK_PREMIUM : count * BASE_PREMIUMS[type];
  }
  return sum;
}
EOF
